-- 110: merch catalog (Imam, 2026-11-24). Products, colours, sizes and
-- logo spots are edited in Studio > Admin > Merch catalog instead of code.
-- One row per product the 3D designer can draw; data holds the editable
-- fields, checked by parseMerchProduct (web-bossmedia/lib/merch.mjs) on
-- every write and read. Products are hidden, never deleted: merch_orders
-- keeps product_id as text. Additive only: no existing table changes.
CREATE TABLE IF NOT EXISTS merch_products (
  id TEXT PRIMARY KEY CHECK (id ~ '^[a-z0-9][a-z0-9-]{1,39}$'),
  data JSONB NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_by UUID NULL REFERENCES users(id) ON DELETE SET NULL
);

